        input           addr;
        input [15:0]    data;
        begin
            @(posedge wb_clk_i);
            wb_adr_i <= addr;
            wb_dat_i <= data;
            wb_we_i  <= 1;
            wb_cyc_i <= 1;
            wb_stb_i <= 1;
            wait(wb_ack_o);
            @(posedge wb_clk_i);
            wb_cyc_i <= 0;
            wb_stb_i <= 0;
            wb_we_i  <= 0;
        end
        endtask

    task wb_read;

        input           addr;
        begin
            @(posedge wb_clk_i);
            wb_adr_i <= addr;
            wb_we_i  <= 0;
            wb_cyc_i <= 1;
            wb_stb_i <= 1;
