                #40;
            end
            @(posedge wb_clk_i);

            #1;


            check_outputs(14'h0000, 1'b1, 1'b0, 16'hzzzz);
        end
        endtask

    task testcase005;

        begin
            test_num = 5;
            $display("Test Case %0d: Max LED Value", test_num);
            reset_dut();
            wb_write(1'b0, 16'h3FFF);
            #10;
            #1;

            check_outputs(14'h3FFF, 1'b0, 1'b0, 16'hzzzz);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

