module top_module(
  input signed [R-1:0] in,
  input clk, // Added clk as an input
  input [31:0] M, // Changed M and N to be of size
  input [31:0] N,
  output signed [S-1:0] out
);parameter R = 16; // number of bits in input signal
parameter S = 16; // number of bits in output signal

// Internal signals
reg [31:0] count;       // Added to track the count for the comb filter
reg [31:0] count2;      // Added to track the count for the second comb filter

// Comb filter
reg signed [R-1:0] comb_out;
always @ (posedge clk) begin
  if (count == M-1) begin
    comb_out <= in;
    count <= 0;
  end else begin
    comb_out <= 0;
    count <= count + 1;
  end
end

// Integrator stages
reg signed [R-1:0] int_out1;
reg signed [R-1:0] int_out2;
reg signed [R-1:0] int_out3;
// Initialize integrator outputs
initial begin
  int_out1 = 0;
  int_out2 = 0;
  int_out3 = 0;
end
always @ (posedge clk) begin
  int_out1 <= int_out1 + comb_out;
  int_out2 <= int_out2 + int_out1;
  int_out3 <= int_out3 + int_out2;
  // Further integrators can be added here
end

// Second comb filter
reg signed [S-1:0] comb2_out;
always @ (posedge clk) begin
  if (count2 == M-1) begin
    comb2_out <= int_out3; // Change int_outN to int_out3
    count2 <= 0;
  end else begin
    comb2_out <= 0;
    count2 <= count2 + 1;
  end
end

// Output
reg signed [S-1:0] out_reg;
always @ (posedge clk) begin
  out_reg <= comb2_out;
end
assign out = out_reg;

endmodule

