description:
Implement the Verilog module based on the following description.
We want to create a module that:

// (1) receives a 4-bit binary number,
// (2) calculates the sum of the digits,
// (3) outputs the sum on 'sum_digits[3:0]',
// (4) provides a reset mechanism to reset the output.

// The input binary number is available on the input signal 'binary_num'. The reset signal is active high synchronous.

module sum_digits_module(
    input wire clk,
    input wire reset,
    input wire [3:0] binary_num,
    output reg [3:0] sum_digits
);

code:
module sum_digits_module(
    input wire clk,
    input wire reset,
    input wire [3:0] binary_num,
    output reg [3:0] sum_digits
);

    integer i;

    always @(posedge clk) begin
        if (reset) begin
            sum_digits <= 0;
        end else begin
            sum_digits <= 0;
            for (i = 0; i < 4; i = i + 1) begin
                sum_digits <= sum_digits + binary_num[i];
            end
        end
    end

endmodule

