description:
Develop a PWM (Pulse Width Modulation) LED controller that produces a variable brightness output for an LED based on an 8-bit duty cycle input. The module operates with a 50 MHz clock, generating a PWM signal with a 2-second total period. The duty cycle determines the proportion of time the LED is turned ON during each period by adjusting the pulse width, thereby controlling the LED's brightness proportionally between OFF and ON states.
module top_module(
  input clk,
  input [7:0] duty_cycle,
  output reg led
);

code:
module top_module(
  input clk,
  input [7:0] duty_cycle,
  output reg led
);reg [31:0] counter;
reg pwm;

always @(posedge clk) begin
  if (counter >= 2000000) begin // 50 MHz clock, 2 second period
    counter <= 0;
  end else begin
    counter <= counter + 1;
  end

  if (counter < duty_cycle * 20000) begin // adjust duty cycle
    pwm <= 1;
  end else begin
    pwm <= 0;
  end

  if (pwm) begin
    led <= 1;
  end else begin
    led <= 0;
  end
end

endmodule

