                expected_bgeu === (expected_bgeu ^ bgeu ^ expected_bgeu) &&
                expected_eq === (expected_eq ^ eq ^ expected_eq) &&
                expected_res === (expected_res ^ res ^ expected_res)) begin
                $display("PASS");
                $display("  Outputs: bge=%b, bgeu=%b, eq=%b, res=%h",
                         bge, bgeu, eq, res);
