                         expected_bge, expected_bgeu, expected_eq, expected_res);
                $display("  Got:      bge=%b, bgeu=%b, eq=%b, res=%h",
                         bge, bgeu, eq, res);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

endmodule

