        in_data = 8'h11;
        @(posedge clk);
        @(negedge clk);
        in_data = 8'h22;
        @(posedge clk);
        #1;
        #1;

        check_outputs(8'h22);
    end
        endtask

    task testcase005;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Hold Value", test_num);
        reset_dut();
        @(negedge clk);
        wenb = 0;
        in_data = 8'h57;
        @(posedge clk);
        @(negedge clk);
        wenb = 1;
        in_data = 8'h00;
        @(posedge clk);
        #1;
        #1;

        check_outputs(8'h57);
    end
        endtask

    task testcase006;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Reset Priority", test_num);
        reset_dut();
        @(negedge clk);
        wenb = 0;
        in_data = 8'hFF;
        reset = 1;
        @(posedge clk);
        #1;
        #1;

        check_outputs(8'h00);
    end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("top_module Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [7:0] expected_reg_0x57;
        begin
            if (expected_reg_0x57 === (expected_reg_0x57 ^ reg_0x57 ^ expected_reg_0x57)) begin
                $display("PASS");
                $display("  Outputs: reg_0x57=%h",
                         reg_0x57);
                pass_count = pass_count + 1;
