module top_module(
    input clk,
    input reset,
    input data_in,
    output reg data_out
);// Define the delay time in clock cycles
    parameter DELAY_TIME = 5;

    // Define a counter to keep track of the delay time
    reg [31:0] counter = 0;

    // Define a register to hold the delayed input signal
    reg delayed_data;

    always @(posedge clk) begin
        if (reset) begin
            // Reset the counter and delayed_data register
            counter <= 0;
            delayed_data <= 0;
        end else begin
            // Increment the counter
            counter <= counter + 1;

            if (counter == DELAY_TIME) begin
                // Output the delayed input signal
                data_out <= delayed_data;

                // Store the current input signal for the next cycle
                delayed_data <= data_in;

                // Reset the counter
                counter <= 0;
            end
        end
    end

endmodule

