description:
Design a digital phase-locked loop (PLL) that generates a clock output signal, c0, based on an input clock signal, inclk0. The module incorporates a parameterized division factor, DIV_FACTOR, allowing the output frequency to be a fraction of the input frequency. It utilizes a counter to count the number of incoming clock cycles and toggles the output clock signal, clk_out, every DIV_FACTOR cycles, effectively creating a divided clock output. The output c0 reflects this toggled signal as the final clock output for downstream circuits.
module top_module(
    inclk0,
    c0
);

code:
module top_module(
    inclk0,
    c0
);parameter   integer   DIV_FACTOR = 2;

    input       inclk0;
    output      c0;

    reg         [31:0]   counter;
    reg                   clk_out;

    always @(posedge inclk0) begin
        if (counter == DIV_FACTOR - 1) begin
            counter <= 0;
            clk_out <= ~clk_out;
        end else begin
            counter <= counter + 1;
        end
    end

    assign c0 = clk_out;

endmodule

