description:
Implement the Verilog module based on the following description.
We want to create a 4-bit register that:

// (1) takes a 4-bit data input 'd',
// (2) has a clock input 'clk',
// (3) has an active-low enable input 'en_n',
// (4) outputs 'q' which holds the value of 'd' on the rising edge of 'clk' when 'en_n' is low.

module register_4bit(
    input wire [3:0] d,
    input wire clk,
    input wire en_n,
    output reg [3:0] q
);

code:
module register_4bit(
    input wire [3:0] d,
    input wire clk,
    input wire en_n,
    output reg [3:0] q
);

    always @(posedge clk) begin
        if (!en_n)
            q <= d;
    end

endmodule

